using System;using System.Collections.Generic;using System.Linq;using System.Web.Mvc;using System.Data.Entity;using _25dh110973_LTW.Models;using _25dh110973_LTW.Models.ViewModel;
namespace _25dh110973_LTW.Controllers {[Authorize] public class OrderController:Controller {MyStoreEntities1 db=new MyStoreEntities1();
 public ActionResult Checkout(){var cart=Session["Cart"] as List<CartItem>;if(cart==null||!cart.Any())return RedirectToAction("Index","Cart");var c=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name);if(c==null)return RedirectToAction("ProfileInfo","Account");ViewBag.Address=c.CustomerAddress;return View(cart);}
 [HttpPost,ValidateAntiForgeryToken]public ActionResult Checkout(string address){var cart=Session["Cart"] as List<CartItem>;if(cart==null||!cart.Any())return RedirectToAction("Index","Cart");if(String.IsNullOrWhiteSpace(address)){ModelState.AddModelError("","Vui lòng nhập địa chỉ giao hàng");return View(cart);}var c=db.Customers.FirstOrDefault(x=>x.Username==User.Identity.Name);if(c==null)return RedirectToAction("ProfileInfo","Account");using(var tx=db.Database.BeginTransaction()){try{var ids=cart.Select(x=>x.ProductID).ToList();var products=db.Products.Where(x=>ids.Contains(x.ProductID)).ToList();if(products.Count!=ids.Distinct().Count()){ModelState.AddModelError("","Có sản phẩm không còn tồn tại");return View(cart);}var order=new Order{CustomerID=c.CustomerID,OrderDate=DateTime.Now,AddressDelivery=address.Trim(),PaymentStatus="Chưa thanh toán",TotalAmount=0};foreach(var item in cart){var p=products.First(x=>x.ProductID==item.ProductID);order.OrderDetails.Add(new OrderDetail{ProductID=p.ProductID,Quantity=item.Quantity,UnitPrice=p.ProductPrice});order.TotalAmount+=item.Quantity*p.ProductPrice;}db.Orders.Add(order);db.SaveChanges();tx.Commit();Session.Remove("Cart");return RedirectToAction("OrderSuccess",new{id=order.OrderID});}catch{tx.Rollback();ModelState.AddModelError("","Không lưu được đơn hàng. Kiểm tra kết nối SQL Server.");return View(cart);}}}
 public ActionResult OrderSuccess(int id){var o=db.Orders.Include(x=>x.Customer).FirstOrDefault(x=>x.OrderID==id&&x.Customer.Username==User.Identity.Name);if(o==null)return HttpNotFound();return View(o);}
 public ActionResult OrderHistory(){var orders=db.Orders.Include(x=>x.Customer).Where(x=>x.Customer.Username==User.Identity.Name).OrderByDescending(x=>x.OrderDate).ToList();return View(orders);}
 public ActionResult Details(int id){var o=db.Orders.Include(x=>x.Customer).Include(x=>x.OrderDetails.Select(d=>d.Product)).FirstOrDefault(x=>x.OrderID==id&&x.Customer.Username==User.Identity.Name);if(o==null)return HttpNotFound();return View(o);}
 } }